  CONSTRAINT `FKjhowo3737lrtdevhgy7qut2ia` FOREIGN KEY (`dang_bai_id`) REFERENCES `dang_bai` (`dang_bai_id`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bài nộp của HS — nam_hoc: JOIN bai_tap→lop_hoc; hoc_ky: JOIN bai_tap.hoc_ky';
