INSERT INTO `bai_nop` VALUES (1,1,1,NULL,NULL,NULL,10.00,20,NULL,1,'DA_CHAM',0,'2026-06-18 09:00:00'),(2,1,2,NULL,NULL,NULL,4.00,0,NULL,1,'DA_CHAM',1,'2026-06-21 10:00:00'),(3,1,4,NULL,NULL,NULL,9.50,20,NULL,1,'DA_CHAM',0,'2026-06-19 14:00:00'),(4,1,5,NULL,NULL,NULL,6.00,0,NULL,1,'DA_NOP',0,'2026-06-20 08:00:00'),(5,2,1,NULL,'Gia đình em có bốn người: bố, mẹ, em và em gái. Bố em là bộ đội, mẹ em là giáo viên. Em rất yêu gia đình của mình.',NULL,NULL,15,NULL,1,'DA_CHAM',0,'2026-06-23 19:00:00'),(6,2,2,NULL,'Gia dinh em',NULL,NULL,0,NULL,1,'YC_LAM_LAI',0,'2026-06-24 20:00:00'),(7,2,4,NULL,'Gia đình em có ông, bà, bố, mẹ và em. Mỗi buổi tối cả nhà cùng ăn cơm và kể chuyện vui. Em rất hạnh phúc.',NULL,NULL,15,NULL,1,'DA_CHAM',0,'2026-06-22 18:00:00'),(8,2,5,NULL,'Gia đình em có...',NULL,NULL,0,NULL,1,'LUU_NHAP',0,NULL),(9,3,3,NULL,NULL,NULL,10.00,25,NULL,1,'DA_CHAM',0,'2026-06-20 09:00:00'),(10,3,8,NULL,NULL,NULL,7.00,25,NULL,1,'DA_CHAM',1,'2026-06-23 11:00:00'),(11,3,9,NULL,NULL,NULL,5.00,0,NULL,1,'DA_NOP',0,'2026-06-22 07:30:00'),(12,4,3,NULL,'Ngày xưa có cây bàng cổ thụ đứng trước ngõ nhà em. Mỗi mùa hè, tán bàng xanh mát che bóng cho cả xóm.',NULL,NULL,20,NULL,1,'DA_CHAM',0,'2026-06-26 20:00:00'),(13,4,8,NULL,'Cây bàng trước ngõ nhà em rất to. Em thích ngồi học bài dưới gốc cây vào buổi chiều.',NULL,NULL,20,NULL,1,'DA_CHAM',0,'2026-06-27 19:30:00'),(14,5,10,NULL,NULL,NULL,10.00,30,NULL,1,'DA_CHAM',0,'2026-07-03 09:00:00'),(15,5,11,NULL,NULL,NULL,7.50,30,NULL,1,'DA_CHAM',0,'2026-07-04 15:00:00'),(16,5,12,NULL,NULL,NULL,5.00,0,NULL,1,'DA_CHAM',1,'2026-07-06 21:00:00'),(17,6,10,NULL,'Giờ ra chơi, sân trường rộn ràng tiếng cười đùa của các bạn học sinh. Có bạn chơi nhảy dây, có bạn đá cầu.',NULL,NULL,0,NULL,1,'DA_NOP',0,'2026-07-08 10:00:00'),(18,7,14,NULL,NULL,NULL,9.00,0,NULL,1,'DA_NOP',0,'2026-07-08 08:00:00'),(19,11,1,1,NULL,NULL,0.00,0,'{\"dapAnDungId\": \"b\"}',1,'DA_NOP',0,'2026-07-19 05:55:06'),(20,12,1,6,NULL,NULL,10.00,0,'{\"dapAnDungId\": \"b\"}',1,'DA_NOP',0,'2026-07-19 05:56:11'),(21,13,1,2,NULL,NULL,5.00,0,'{\"capChon\": [{\"phaiId\": \"R1\", \"traiId\": \"L1\"}, {\"phaiId\": \"R1\", \"traiId\": \"L2\"}]}',1,'DA_NOP',0,'2026-07-19 05:56:11'),(22,14,1,5,NULL,NULL,5.00,0,'{\"traLoiTheoCho\": {\"c1\": \"B?N\", \"c2\": \"2\"}}',1,'DA_NOP',0,'2026-07-19 05:56:11'),(23,15,1,9,NULL,NULL,10.00,0,'{\"traLoiTheoCho\": {\"c1\": \"BỐN\", \"c2\": \"2\"}}',1,'DA_NOP',0,'2026-07-19 05:56:52'),(24,16,1,10,NULL,NULL,10.00,0,'{\"capChon\": [{\"phaiId\": \"R1\", \"traiId\": \"L1\"}, {\"phaiId\": \"R2\", \"traiId\": \"L2\"}]}',1,'DA_NOP',0,'2026-07-19 05:58:34'),(26,17,1,NULL,'Bai lam test huy hieu tu dong',NULL,NULL,0,NULL,1,'DA_NOP',0,'2026-07-19 09:44:43'),(27,18,1,NULL,'Bai lam thu 2',NULL,NULL,0,NULL,1,'DA_NOP',0,'2026-07-19 09:45:00'),(28,19,1,3,NULL,NULL,10.00,0,'{\"dapAnDungId\": \"b\"}',1,'DA_NOP',0,'2026-07-19 09:45:46'),(29,20,1,4,NULL,NULL,10.00,0,'{\"dapAnDungId\": \"b\"}',1,'DA_NOP',0,'2026-07-19 09:45:51'),(30,21,1,7,NULL,NULL,10.00,0,'{\"dapAnDungId\": \"b\"}',1,'DA_NOP',0,'2026-07-19 09:45:53'),(31,22,1,8,NULL,NULL,0.00,0,'{\"dapAnDungId\": \"a\"}',1,'DA_NOP',0,'2026-07-19 09:46:28'),(32,23,1,11,NULL,NULL,10.00,0,'{\"dapAnDungId\": \"b\"}',1,'DA_NOP',0,'2026-07-19 09:46:29');
