  `giao_vien_id` bigint unsigned NOT NULL,
  `lop_hoc_id` bigint unsigned NOT NULL,
  `bai_hoc_id` int unsigned DEFAULT NULL COMMENT 'Khác NULL nếu GV giao cả cụm Bài học (giao hết các dang_bai bên trong)',
  `dang_bai_id` int unsigned DEFAULT NULL COMMENT 'Khác NULL nếu GV giao từng Dạng bài lẻ',
  `hoc_ky_id` int unsigned NOT NULL COMMENT 'Học kỳ GV giao bài (snapshot tại thời điểm tạo)',
  `tieu_de` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
