  `hoc_lieu_id` bigint DEFAULT NULL,
  PRIMARY KEY (`bai_tap_id`),
  KEY `fk_bt_hk` (`hoc_ky_id`),
  KEY `fk_bt_giao_vien` (`giao_vien_id`),
  KEY `fk_bt_bai_hoc` (`bai_hoc_id`),
  KEY `fk_bt_dang_bai` (`dang_bai_id`),
  KEY `idx_bai_tap_lop` (`lop_hoc_id`,`hoc_ky_id`,`trang_thai`),
  KEY `fk_bai_tap_hoc_lieu` (`hoc_lieu_id`),
