INSERT INTO `bao_cao_ai_buoi_sang` VALUES (2,3,5,'2026-07-10','Lớp 5A ghi nhận số lượng học sinh có hoạt động học tập và bài tập nộp trong ngày hôm qua là 0. Tỷ lệ tham gia của tổng số 4 học sinh là 0%. Chưa có bài tập nào được nộp, bao gồm cả các bài tập nộp trễ. Cần xem xét nguyên nhân và có biện pháp hỗ trợ để tăng cường sự chủ động của học sinh trong ngày hôm nay.','{\"totalStudents\": 4, \"activeYesterday\": 0, \"submissionsYesterday\": 0, \"avgAutoScoreYesterday\": null, \"lateSubmissionsYesterday\": 0, \"completedSomethingYesterday\": 0, \"notCompletedAssignedContent\": []}','2026-07-10 00:43:11'),(3,1,1,'2026-07-19','Lớp 1A ghi nhận tổng cộng 4 học sinh. Hôm qua, không có học sinh nào tham gia hoạt động học tập. Tương tự, không học sinh nào hoàn thành ít nhất một nội dung và không có bài tập nào được nộp.','{\"totalStudents\": 4, \"activeYesterday\": 0, \"submissionsYesterday\": 0, \"avgAutoScoreYesterday\": null, \"lateSubmissionsYesterday\": 0, \"completedSomethingYesterday\": 0, \"notCompletedAssignedContent\": []}','2026-07-19 05:27:25'),(4,3,7,'2026-07-20','Lớp 2B ghi nhận số lượng học sinh có hoạt động học tập là 0 trong ngày hôm qua. Không có học sinh nào hoàn thành ít nhất một nội dung, cũng như không có bài tập nào được nộp. Tình hình này cần được xem xét và có biện pháp hỗ trợ kịp thời để tăng cường sự tham gia của học sinh vào quá trình học tập.','{\"totalStudents\": 30, \"activeYesterday\": 0, \"submissionsYesterday\": 0, \"avgAutoScoreYesterday\": null, \"lateSubmissionsYesterday\": 0, \"completedSomethingYesterday\": 0, \"notCompletedAssignedContent\": []}','2026-07-20 06:59:27'),(5,1,1,'2026-07-20','Lớp 1A có tổng cộng 30 học sinh tham gia hoạt động học tập ngày hôm qua. Chỉ duy nhất 1 học sinh hoàn thành ít nhất 1 nội dung, còn lại không ai. Tổng số bài tập đã nộp là 13, với điểm trung bình các bài H5P tự động đạt 7,3/10.','{\"totalStudents\": 30, \"activeYesterday\": 1, \"submissionsYesterday\": 13, \"avgAutoScoreYesterday\": 7.272727272727272, \"lateSubmissionsYesterday\": 0, \"completedSomethingYesterday\": 1, \"notCompletedAssignedContent\": []}','2026-07-20 08:23:43');
