--
-- Table structure for table `dang_bai`
--

DROP TABLE IF EXISTS `dang_bai`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dang_bai` (
  `dang_bai_id` int unsigned NOT NULL AUTO_INCREMENT,
  `bai_hoc_id` int unsigned NOT NULL COMMENT 'FK → bai_hoc (cấp Bài học — cấp 3)',
  `book_index_id_ngoai` int unsigned DEFAULT NULL COMMENT 'bookIndexId từ API khi import',
  `ten_dang_bai` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'name: "Khám phá", "Hoạt động", "Luyện tập"',
  `slug` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'slug: "kham-pha", "hoat-dong", "luyen-tap"',
  `so_trang` int DEFAULT NULL,
  `so_thu_tu` int NOT NULL,
  `mon_hoc_id` tinyint unsigned NOT NULL COMMENT 'FK → mon_hoc',
  `loai_noi_dung` enum('H5P','FILE','NATIVE','JSON_TEXT') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'JSON_TEXT' COMMENT 'Cách React render. JSON_TEXT là mặc định cho sách gốc',
  `nguon_goc` enum('HE_THONG','GIAO_VIEN_BO_SUNG') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'HE_THONG',
  `giao_vien_id` bigint unsigned DEFAULT NULL COMMENT 'NULL nếu của HE_THONG',
  `h5p_noi_dung_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `xp_thuong` int NOT NULL,
  `cau_hinh` json DEFAULT NULL COMMENT 'Lưu mọi dữ liệu tùy biến: file_url, text bài đọc, đáp án, props...',
  `ngay_tao` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `dap_an_chuan` json DEFAULT NULL,
  PRIMARY KEY (`dang_bai_id`),
  KEY `fk_db_mon` (`mon_hoc_id`),
  KEY `idx_dang_bai_bai_hoc` (`bai_hoc_id`,`so_thu_tu`),
  KEY `idx_dang_bai_giao_vien` (`giao_vien_id`),
  KEY `idx_dang_bai_h5p_id` (`h5p_noi_dung_id`),
  CONSTRAINT `fk_db_bai_hoc` FOREIGN KEY (`bai_hoc_id`) REFERENCES `bai_hoc` (`bai_hoc_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_db_gv` FOREIGN KEY (`giao_vien_id`) REFERENCES `ho_so_giao_vien` (`giao_vien_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_db_mon` FOREIGN KEY (`mon_hoc_id`) REFERENCES `mon_hoc` (`mon_hoc_id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=1495 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Dạng bài kiêm nội dung học (đa hình qua cau_hinh JSON). GV có thể thêm bài bổ sung.';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `dang_bai`
--

