86,NULL,'Lý thuyết',NULL,NULL,0,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"LY_THUYET\", \"noiDung\": \"Bài toán có \'thêm\' (cho, mua thêm...) thì dùng phép cộng. Bài toán có \'bớt\' (cho đi, ăn mất...) thì dùng phép trừ.\\n\\nVí dụ: Lan có 6 viên kẹo, mẹ cho thêm 3 viên. Lan có tất cả: 6 + 3 = 9 viên (vì đề bài nói \'thêm\' nên dùng phép cộng).\"}','2026-07-20 14:28:24',NULL),(552,86,NULL,'Khám phá',NULL,NULL,1,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"TRAC_NGHIEM\", \"cauHoi\": \"Lan có 12 viên kẹo, Lan cho bạn 4 viên. Hỏi Lan còn lại bao nhiêu viên kẹo?\", \"luaChon\": [{\"id\": \"a\", \"noiDung\": \"8\"}, {\"id\": \"b\", \"noiDung\": \"9\"}, {\"id\": \"c\", \"noiDung\": \"7\"}, {\"id\": \"d\", \"noiDung\": \"16\"}]}','2026-07-20 14:28:24','{\"dapAnDungId\": \"a\"}'),(553,86,NULL,'Hoạt động',NULL,NULL,2,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"NOI_CAP\", \"cauHoi\": \"Nối tình huống với phép tính phù hợp\", \"cotPhai\": [{\"id\": \"R1\", \"noiDung\": \"Phép cộng (+)\"}, {\"id\": \"R2\", \"noiDung\": \"Phép trừ (-)\"}], \"cotTrai\": [{\"id\": \"L1\", \"noiDung\": \"Có thêm\"}, {\"id\": \"L2\", \"noiDung\": \"Bớt đi, cho đi\"}]}','2026-07-20 14:28:24','{\"capDung\": [{\"phaiId\": \"R1\", \"traiId\": \"L1\"}, {\"phaiId\": \"R2\", \"traiId\": \"L2\"}]}'),(554,86,NULL,'Luyện tập 1',NULL,NULL,3,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\", \"cauHoi\": \"An có 18 quả bóng, mẹ cho thêm 1 quả. Hỏi An có tất cả bao nhiêu quả bóng? Đáp số: ___\", \"danhSachCho\": [\"cho1\"]}','2026-07-20 14:28:24','{\"dapAnTheoCho\": {\"cho1\": [\"19\"]}}'),(555,86,NULL,'Luyện tập 2',NULL,NULL,4,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\", \"cauHoi\": \"An có 13 quả bóng, mẹ cho thêm 4 quả. Hỏi An có tất cả bao nhiêu quả bóng? Đáp số: ___\", \"danhSachCho\": [\"cho1\"]}','2026-07-20 14:28:24','{\"dapAnTheoCho\": {\"cho1\": [\"17\"]}}'),(556,86,NULL,'Luyện tập 3',NULL,NULL,5,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\"