 hình chữ nhật = (chiều dài + chiều rộng) x 2. Diện tích hình chữ nhật = chiều dài x chiều rộng. Diện tích hình vuông = cạnh x cạnh.\\n\\nVí dụ: hình chữ nhật dài 5cm, rộng 3cm.\\nChu vi = (5 + 3) x 2 = 16cm. Diện tích = 5 x 3 = 15cm².\"}','2026-07-20 14:28:24',NULL),(744,205,NULL,'Khám phá',NULL,NULL,1,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"TRAC_NGHIEM\", \"cauHoi\": \"Hình chữ nhật có chiều dài 9cm, chiều rộng 3cm. Chu vi hình đó là bao nhiêu?\", \"luaChon\": [{\"id\": \"a\", \"noiDung\": \"24\"}, {\"id\": \"b\", \"noiDung\": \"26\"}, {\"id\": \"c\", \"noiDung\": \"22\"}, {\"id\": \"d\", \"noiDung\": \"27\"}]}','2026-07-20 14:28:24','{\"dapAnDungId\": \"a\"}'),(745,205,NULL,'Hoạt động',NULL,NULL,2,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"NOI_CAP\", \"cauHoi\": \"Nối công thức với tên gọi\", \"cotPhai\": [{\"id\": \"R1\", \"noiDung\": \"Chu vi hình chữ nhật\"}, {\"id\": \"R2\", \"noiDung\": \"Diện tích hình vuông\"}, {\"id\": \"R3\", \"noiDung\": \"Diện tích hình chữ nhật\"}], \"cotTrai\": [{\"id\": \"L1\", \"noiDung\": \"(dài + rộng) x 2\"}, {\"id\": \"L2\", \"noiDung\": \"cạnh x cạnh\"}, {\"id\": \"L3\", \"noiDung\": \"dài x rộng\"}]}','2026-07-20 14:28:24','{\"capDung\": [{\"phaiId\": \"R1\", \"traiId\": \"L1\"}, {\"phaiId\": \"R2\", \"traiId\": \"L2\"}, {\"phaiId\": \"R3\", \"traiId\": \"L3\"}]}'),(746,205,NULL,'Luyện tập 1',NULL,NULL,3,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\", \"cauHoi\": \"Hình vuông có cạnh 5cm. Diện tích hình đó là ___ cm²\", \"danhSachCho\": [\"cho1\"]}','2026-07-20 14:28:24','{\"dapAnTheoCho\": {\"cho1\": [\"25\"]}}'),(747,205,NULL,'Luyện tập 2',NULL,NULL,4,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\", \"cauHoi\": \"Hình vuông có cạnh 3cm. Diện tích hình đó là ___ cm²\", \"danhSachCho\": [\"cho1\"]}','2026-07-20 14:28:24','{\"dapAnTheoCho\": {\"cho1\": [\"9\"]}}'),(748,205,NULL,'Luyện tập 3',NULL,NULL,5,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\", \"