(767,217,NULL,'Lý thuyết',NULL,NULL,0,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"LY_THUYET\", \"noiDung\": \"Khi biểu thức có nhiều phép cộng, trừ liên tiếp, ta tính lần lượt từ trái sang phải, không được tính phép trừ trước nếu nó nằm sau.\\n\\nVí dụ: 8 - 3 + 2 = ?\\nBước 1: 8 - 3 = 5.\\nBước 2: 5 + 2 = 7.\\nVậy 8 - 3 + 2 = 7.\"}','2026-07-20 14:28:24',NULL),(768,217,NULL,'Khám phá',NULL,NULL,1,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"TRAC_NGHIEM\", \"cauHoi\": \"Tính: 29457 - 2154 + 6599 = ?\", \"luaChon\": [{\"id\": \"a\", \"noiDung\": \"33903\"}, {\"id\": \"b\", \"noiDung\": \"33907\"}, {\"id\": \"c\", \"noiDung\": \"33902\"}, {\"id\": \"d\", \"noiDung\": \"33901\"}]}','2026-07-20 14:28:24','{\"dapAnDungId\": \"c\"}'),(769,217,NULL,'Hoạt động',NULL,NULL,2,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"NOI_CAP\", \"cauHoi\": \"Nối phép tính với kết quả đúng\", \"cotPhai\": [{\"id\": \"R1\", \"noiDung\": \"17637\"}, {\"id\": \"R2\", \"noiDung\": \"18632\"}, {\"id\": \"R3\", \"noiDung\": \"3211\"}], \"cotTrai\": [{\"id\": \"L1\", \"noiDung\": \"31920 - 14283\"}, {\"id\": \"L2\", \"noiDung\": \"50386 - 31754\"}, {\"id\": \"L3\", \"noiDung\": \"34311 - 31100\"}]}','2026-07-20 14:28:24','{\"capDung\": [{\"phaiId\": \"R1\", \"traiId\": \"L1\"}, {\"phaiId\": \"R2\", \"traiId\": \"L2\"}, {\"phaiId\": \"R3\", \"traiId\": \"L3\"}]}'),(770,217,NULL,'Luyện tập 1',NULL,NULL,3,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\", \"cauHoi\": \"Điền số thích hợp: 97899 - 26635 = ___\", \"danhSachCho\": [\"cho1\"]}','2026-07-20 14:28:24','{\"dapAnTheoCho\": {\"cho1\": [\"71264\"]}}'),(771,217,NULL,'Luyện tập 2',NULL,NULL,4,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\", \"cauHoi\": \"Điền số thích hợp: 43963 - 11597 = ___\", \"danhSachCho\": [\"cho1\"]}','2026-07-20 14:28:24','{\"dapAnTheoCho\": {\"cho1\": [\"32366\"]}}'),(772,217,NULL,'Luyện tập 3',NULL,NULL,5,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\"