','HE_THONG',NULL,NULL,0,'{\"loai\": \"LY_THUYET\", \"noiDung\": \"Số liền sau của một số là số lớn hơn số đó 1 đơn vị. Số liền trước là số nhỏ hơn số đó 1 đơn vị.\\n\\nVí dụ: cho số 5.\\n- Số liền sau của 5 là 5 + 1 = 6.\\n- Số liền trước của 5 là 5 - 1 = 4.\\nVậy ta có dãy: 4, 5, 6 (mỗi số sau hơn số trước 1 đơn vị).\", \"trucQuan\": {\"icon\": \"?\", \"type\": \"dem_so\", \"count\": 5}}','2026-07-20 14:28:24',NULL),(792,234,NULL,'Khám phá',NULL,NULL,1,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"TRAC_NGHIEM\", \"cauHoi\": \"Số liền sau của 2775 là số nào?\", \"luaChon\": [{\"id\": \"a\", \"noiDung\": \"2776\"}, {\"id\": \"b\", \"noiDung\": \"2777\"}, {\"id\": \"c\", \"noiDung\": \"2775\"}, {\"id\": \"d\", \"noiDung\": \"2774\"}]}','2026-07-20 14:28:24','{\"dapAnDungId\": \"a\"}'),(793,234,NULL,'Hoạt động',NULL,NULL,2,1,'JSON_TEXT','HE_THONG',NULL,NULL,0,'{\"loai\": \"NOI_CAP\", \"cauHoi\": \"Nối mỗi số với số liền trước của nó\", \"cotPhai\": [{\"id\": \"R1\", \"noiDung\": \"1408\"}, {\"id\": \"R2\", \"noiDung\": \"47776\"}, {\"id\": \"R3\", \"noiDung\": \"59424\"}], \"cotTrai\": [{\"id\": \"L1\", \"noiDung\": \"1409\"}, {\"id\": \"L2\", \"noiDung\": \"47777\"}, {\"id\": \"L3\", \"noiDung\": \"59425\"}]}','2026-07-20 14:28:24','{\"capDung\": [{\"phaiId\": \"R1\", \"traiId\": \"L1\"}, {\"phaiId\": \"R2\", \"traiId\": \"L2\"}, {\"phaiId\": \"R3\", \"traiId\": \"L3\"}]}'),(794,234,NULL,'Luyện tập 1',NULL,NULL,3,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\", \"cauHoi\": \"Điền số còn thiếu vào dãy số: 29921, ___, 29923, ___, 29925\", \"danhSachCho\": [\"cho1\", \"cho2\"]}','2026-07-20 14:28:24','{\"dapAnTheoCho\": {\"cho1\": [\"29922\"], \"cho2\": [\"29924\"]}}'),(795,234,NULL,'Luyện tập 2',NULL,NULL,4,1,'JSON_TEXT','HE_THONG',NULL,NULL,10,'{\"loai\": \"DIEN_KHUYET\", \"cauHoi\": \"Điền số còn thiếu vào dãy số: 60900, ___, 60902, ___, 60904\", \"danhSachCho\": [\"cho1\", \"cho2\"]}','2026-07-20 14:28:24','{\"dapAnTheoCho\": {\"cho1\": [\"609