DROP TABLE IF EXISTS `danh_gia_bai_lam`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `danh_gia_bai_lam` (
  `danh_gia_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `bai_nop_id` bigint unsigned NOT NULL,
  `giao_vien_id` bigint unsigned NOT NULL,
  `diem_so` decimal(4,1) DEFAULT NULL,
  `xep_loai` enum('HOAN_THANH_TOT','HOAN_THANH','CHUA_HOAN_THANH') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nhan_xet` text COLLATE utf8mb4_unicode_ci,
  `hanh_dong` enum('DUYET','YC_LAM_LAI') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DUYET',
  `thoi_diem_cham` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`danh_gia_id`),
  UNIQUE KEY `uk_bai_nop` (`bai_nop_id`),
  KEY `fk_dg_giao_vien` (`giao_vien_id`),
  CONSTRAINT `fk_dg_bai_nop` FOREIGN KEY (`bai_nop_id`) REFERENCES `bai_nop` (`bai_nop_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_dg_giao_vien` FOREIGN KEY (`giao_vien_id`) REFERENCES `ho_so_giao_vien` (`giao_vien_id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_diem` CHECK (((`diem_so` is null) or (`diem_so` between 0 and 10)))
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Điểm số + nhận xét GV (1-1 với bai_nop) — theo TT27/2020';
