INSERT INTO `danh_gia_bai_lam` VALUES (1,1,1,10.0,'HOAN_THANH_TOT','Con làm bài rất tốt, chính xác 100%!','DUYET','2026-06-19 08:00:00'),(2,2,1,4.0,'CHUA_HOAN_THANH','Con cần luyện tập thêm phép cộng, nộp bài trễ hạn.','DUYET','2026-06-22 08:00:00'),(3,3,1,9.5,'HOAN_THANH_TOT','Rất xuất sắc, con tiến bộ nhiều!','DUYET','2026-06-20 08:00:00'),(4,5,1,8.0,'HOAN_THANH','Đoạn văn khá tốt, cần thêm chi tiết miêu tả.','DUYET','2026-06-24 09:00:00'),(5,6,1,3.0,'CHUA_HOAN_THANH','Bài viết quá ngắn, con hãy viết lại đầy đủ hơn nhé.','YC_LAM_LAI','2026-06-25 09:00:00'),(6,7,1,9.0,'HOAN_THANH_TOT','Văn phong sinh động, giàu cảm xúc!','DUYET','2026-06-23 09:00:00'),(7,9,2,10.0,'HOAN_THANH_TOT','Xuất sắc, không sai câu nào!','DUYET','2026-06-21 08:00:00'),(8,10,2,7.0,'HOAN_THANH','Nộp trễ hạn, cần chú ý deadline hơn.','DUYET','2026-06-24 08:00:00'),(9,12,2,9.0,'HOAN_THANH_TOT','Kể chuyện mạch lạc, cảm xúc chân thật.','DUYET','2026-06-27 09:00:00'),(10,13,2,7.5,'HOAN_THANH','Bài kể tốt, cần thêm câu mở đầu hấp dẫn hơn.','DUYET','2026-06-28 09:00:00'),(11,14,4,10.0,'HOAN_THANH_TOT','Con làm bài rất nhanh và chính xác!','DUYET','2026-07-04 08:00:00'),(12,15,4,7.5,'HOAN_THANH','Còn sai vài phép chia, cần ôn lại bảng cửu chương.','DUYET','2026-07-05 08:00:00'),(13,16,4,5.0,'CHUA_HOAN_THANH','Nộp trễ và làm sai khá nhiều, cần cố gắng hơn.','DUYET','2026-07-07 08:00:00');
