LOCK TABLES `goi_y_ai_nhan_xet` WRITE;
/*!40000 ALTER TABLE `goi_y_ai_nhan_xet` DISABLE KEYS */;
INSERT INTO `goi_y_ai_nhan_xet` VALUES (1,5,'{\"isLate\": false, \"autoScore\": null, \"textLength\": 114}','[\"Con thật thông minh khi đã viết được những điềuLovely về gia đình mình! Cô/Thầy rất vui vì con biết bày tỏ tình cảm yêu thương với bố mẹ, em gái. Tiếp tục cố gắng nhé, con sẽ ngày càng viết hay hơn đấy!\", \"Con à, bài viết của con đã thật tốt! Để bài làm thêm sinh động hơn, con thử kể thêm một vài điều đặc biệt về bố mẹ và em gái nhé. Ví dụ, con có thể nói bố mẹ con giúp con những gì hay con thích chơi với em gái ở đâu.\", \"Con ơi, cô/thầy thấy bài viết của con đã nêu được thông tin cơ bản về gia đình rất tốt. Để bài văn thêm sinh động, con có thể kể thêm một vài hoạt động đáng nhớ của cả nhà nhé!\"]','NHAP','2026-07-10 00:43:22'),(2,5,'{\"isLate\": false, \"autoScore\": null, \"textLength\": 114}','[\"Con thật thông minh khi đã miêu tả rõ ràng về gia đình mình, thể hiện tình cảm yêu thương bố mẹ và em gái. Cô/Thầy thấy con đã viết bài rất tốt, tiếp tục cố gắng nhé, con sẽ ngày càng giỏi hơn nữa đấy!\", \"Con à, bài viết của con rất hay, đã nêu được thông tin cơ bản về gia đình. Để bài làm thêm sinh động, con có thể kể thêm một vài hoạt động vui vẻ mà cả nhà cùng nhau trải nghiệm nhé. Con thử tưởng tượng và miêu tả những khoảnh khắc đó xem sao, chắc chắn con sẽ có một bài viết thật đáng yêu đấy!\", \"Con ơi, cô/thầy thấy bài viết của con đã nêu được thông tin cơ bản về gia đình rất tốt lắm đấy! Con có thể thêm vào một vài chi tiết thú vị hơn nữa để câu chuyện trở nên sinh động và gần gũi hơn nhé.\"]','NHAP','2026-07-10 16:23:28'),(3,5,'{\"isLate\": false, \"autoScore\": null, \"textLength\": 114}','[\"Con ơi, bài viết của con thật hay! Con đã diễn tả rõ ràng tình cảm yêu thương gia đình và mô tả được thành viên trong nhà một cách gần gũi. Cô/Thầy rất khích lệ con tiếp tục chăm chỉ để biết thêm nhiều điều thú vị nhé!\", \"Con à, bài viết của con thật hay, đã nêu được thông tin cơ bản về gia đình. Để bài viết thêm sinh động, con có thể kể thêm một vài hoạt động thường ngày mà cả nhà cùng nhau làm được nhé. Con thử tưởng tượng và viết về điều đó xem sao, chắc chắn bố mẹ con sẽ rất vui đấy!\", \"Con ơi, cô/thầy thấy bài viết của con đã nêu được những thành viên trong gia đình một cách rõ ràng rất tốt đó. Con có thể thêm vào vài chi tiết nhỏ về những hoạt động vui vẻ mà cả nhà cùng làm để bài viết thêm sinh động nhé.\"]','NHAP','2026-07-10 16:23:40'),(4,5,'{\"isLate\": false, \"autoScore\": null, \"textLength\": 114}','[\"Con ơi, bài viết của con thật tốt lắm! Con đã mô tả rõ ràng về tình cảm yêu thương gia đình và những thành viên trong nhà. Cô/thầy rất khâm phục sự chân thành của con, mong rằng con sẽ tiếp tục cố gắng để hoàn thiện hơn nữa nhé!\", \"Con à, bài viết của con thật hay, đã kể rõ về các thành viên trong gia đình. Con có thể thêm một vài chi tiết thú vị hơn nữa để người nghe/đọc hiểu rõ hơn về bố mẹ và em gái nhé. Thử nhớ lại những hoạt động vui vẻ mà cả nhà cùng nhau trải nghiệm để làm cho bài viết thêm sinh động, con thấy tự hào đấy!\", \"Con ơi, cô/thầy thấy đoạn văn của con mô tả về gia đình thật đáng yêu và đầy tình cảm. Con có thể thêm một vài chi tiết nhỏ để câu chuyện trở nên sinh động hơn nữa nhé, ví dụ như con thích làm gì cùng bố mẹ.\"]','NHAP','2026-07-10 16:23:53');
/*!40000 ALTER TABLE `goi_y_ai_nhan_xet` ENABLE KEYS */;
UNLOCK TABLES;

