--
-- Table structure for table `phien_dang_nhap`
--

DROP TABLE IF EXISTS `phien_dang_nhap`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `phien_dang_nhap` (
  `phien_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nguoi_dung_id` bigint unsigned NOT NULL,
  `refresh_token` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA-256 hash của refresh token gốc',
  `ten_thiet_bi` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-Agent rút gọn: Chrome/Windows, iPhone App',
  `dia_chi_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP đăng nhập lần đầu, hỗ trợ IPv4 và IPv6',
  `het_han` datetime NOT NULL COMMENT 'Thời điểm token hết hạn (thường 30 ngày)',
  `thoi_diem_tao` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `thoi_diem_su_dung_cuoi` datetime DEFAULT NULL COMMENT 'Cập nhật mỗi lần refresh — phát hiện token cũ bị tái sử dụng',
  `da_thu_hoi` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = bị revoke (đăng xuất hoặc phát hiện bất thường)',
  PRIMARY KEY (`phien_id`),
  UNIQUE KEY `uk_refresh_token` (`refresh_token`(64)),
  KEY `idx_phien_nguoi_dung` (`nguoi_dung_id`,`da_thu_hoi`,`het_han`),
  CONSTRAINT `fk_phien_nd` FOREIGN KEY (`nguoi_dung_id`) REFERENCES `nguoi_dung` (`nguoi_dung_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=191 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='JWT Refresh Token - 1 user nhiều phiên, có thể revoke từng phiên hoặc toàn bộ';
/*!40101 SET character_set_client = @saved_cs_client */;

