--
-- Table structure for table `thong_bao`
--

DROP TABLE IF EXISTS `thong_bao`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `thong_bao` (
  `thong_bao_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nguoi_gui_id` bigint unsigned NOT NULL,
  `lop_hoc_id` bigint unsigned DEFAULT NULL COMMENT 'NULL nếu là thông báo hệ thống toàn trường',
  `tieu_de` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `noi_dung` text COLLATE utf8mb4_unicode_ci,
  `file_dinh_kem` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loai_thong_bao` enum('NOI_BO','KHEN_THUONG','NHAC_NHO','HE_THONG') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOI_BO',
  `la_ghim` tinyint(1) NOT NULL DEFAULT '0',
  `ngay_dang` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `doi_tuong_nhan` enum('TAT_CA','PHU_HUYNH','HOC_SINH') COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`thong_bao_id`),
  KEY `fk_tb_nguoi_gui` (`nguoi_gui_id`),
  KEY `idx_thong_bao_lop` (`lop_hoc_id`,`la_ghim`,`ngay_dang`),
  CONSTRAINT `fk_tb_lop` FOREIGN KEY (`lop_hoc_id`) REFERENCES `lop_hoc` (`lop_hoc_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_tb_nguoi_gui` FOREIGN KEY (`nguoi_gui_id`) REFERENCES `nguoi_dung` (`nguoi_dung_id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Thông báo nội bộ lớp và thông báo hệ thống';
/*!40101 SET character_set_client = @saved_cs_client */;

