--
-- Table structure for table `tien_do_hoc_sinh`
--

DROP TABLE IF EXISTS `tien_do_hoc_sinh`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tien_do_hoc_sinh` (
  `tien_do_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `hoc_sinh_id` bigint unsigned NOT NULL,
  `dang_bai_id` int unsigned NOT NULL,
  `hoc_ky_id` int unsigned NOT NULL COMMENT 'Học kỳ (snapshot khi bắt đầu học)',
  `phan_tram_hoan_thanh` smallint NOT NULL,
  `thoi_gian_hoc` int unsigned NOT NULL DEFAULT '0' COMMENT 'Tổng giây đã học trong kỳ này',
  `lan_xem_cuoi` datetime DEFAULT NULL,
  `da_hoan_thanh` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`tien_do_id`),
  UNIQUE KEY `uk_hs_dangbai_ky` (`hoc_sinh_id`,`dang_bai_id`,`hoc_ky_id`),
  KEY `fk_td_hk` (`hoc_ky_id`),
  KEY `fk_td_db` (`dang_bai_id`),
  KEY `idx_tien_do_hs` (`hoc_sinh_id`,`hoc_ky_id`,`da_hoan_thanh`),
  CONSTRAINT `fk_td_db` FOREIGN KEY (`dang_bai_id`) REFERENCES `dang_bai` (`dang_bai_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_td_hk` FOREIGN KEY (`hoc_ky_id`) REFERENCES `hoc_ky` (`hoc_ky_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_td_hs` FOREIGN KEY (`hoc_sinh_id`) REFERENCES `ho_so_hoc_sinh` (`hoc_sinh_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_phan_tram` CHECK ((`phan_tram_hoan_thanh` between 0 and 100))
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tiến độ dạng bài theo năm học + học kỳ — tránh ghi đè khi học lại; đầu vào AI';
/*!40101 SET character_set_client = @saved_cs_client */;

